// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 로그인" (6b50aaa3b9764717a560dbf53ef18d1a).
// #21: 로그인 폼, 비밀번호 표시/숨기기, 버튼 활성화 조건, 실패 모달을 연결했다.
// #189: docs/ui-guide.md 공통 값(uiStyles, ConfirmModal)으로 바꿨다.
import { useState, type FormEvent } from "react";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage } from "../api/client";
import { useAuth } from "../hooks/useAuth";
import AuthHeader from "../components/AuthHeader";
import AuthShowcase from "../components/AuthShowcase";
import ConfirmModal from "../components/ConfirmModal";
import Footer from "../components/Footer";
import { HEADER_BUTTON_CLASS, HEADER_BUTTON_COLOR } from "../components/headerStyles";
import { buttonClass, CARD, FOCUS, INPUT, PAGE_BACKGROUND } from "../components/uiStyles";
import "./Login.css";

// REQ-LOGIN-007: 로그인 성공 시 이동할 메인 페이지 (전체 질문 목록)
const MAIN_PATH = "/questions";
const LOGIN_FAILED_MESSAGE = "아이디 또는 비밀번호가 일치하지 않아요";

const ICON = "material-symbols-outlined text-[18px] leading-none";
const LINK = `rounded hover:text-devin-ink hover:underline ${FOCUS}`;

interface LoginError {
  title: string;
  detail: string | null;
}

// 실패 모달: 공통 확인 모달에 닫기 버튼만 두고, 계정 찾기 링크를 함께 보여 준다.
function LoginFailedDialog({ error, onClose }: { error: LoginError; onClose: () => void }) {
  return (
    <ConfirmModal
      message={error.detail ?? "입력한 계정 정보를 다시 확인해 주세요."}
      title={error.title}
      onCancel={onClose}
    >
      {!error.detail && (
        <p className="text-devin-gray">
          영문 대소문자를 구분하니{" "}
          <kbd className="px-1.5 py-0.5 bg-devin-tag rounded font-mono text-xs font-bold text-devin-ink">Caps Lock</kbd>
          이 켜져 있는지 확인해 주세요.
        </p>
      )}
      <nav aria-label="계정 찾기" className="mt-3 flex items-center gap-2 text-xs font-semibold text-devin-gray">
        <Link className={LINK} to="/find-id">
          아이디 찾기
        </Link>
        <span className="text-devin-gray-light" aria-hidden="true">
          |
        </span>
        <Link className={LINK} to="/find-password">
          비밀번호 찾기
        </Link>
      </nav>
    </ConfirmModal>
  );
}

export default function Login() {
  const navigate = useNavigate();
  const { login, user, initializing } = useAuth();
  const [loginId, setLoginId] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<LoginError | null>(null);

  // 이미 로그인했으면 첫 화면(/) 대신 질문 목록으로 보낸다. 로그인 상태 복구 중에는 폼이 깜빡이지 않게 비워 둔다.
  if (initializing) return null;
  if (user) return <Navigate to={MAIN_PATH} replace />;

  // REQ-LOGIN-004: 아이디·비밀번호를 모두 입력했을 때만 로그인 버튼 활성화
  const canSubmit = loginId.length > 0 && password.length > 0 && !submitting;

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      await login(loginId, password);
      navigate(MAIN_PATH, { replace: true });
    } catch (err) {
      // LOGIN_FAILED는 기본 안내 문구, 정지·탈퇴 등은 서버 메시지를 보여준다.
      const code = getErrorCode(err);
      setError(
        code === "LOGIN_FAILED"
          ? { title: LOGIN_FAILED_MESSAGE, detail: null }
          : { title: "로그인할 수 없어요", detail: getErrorMessage(err) },
      );
      setPassword("");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div id="page-login">
      <div className={`${PAGE_BACKGROUND} min-h-screen flex flex-col justify-between text-devin-ink antialiased`}>
        <AuthHeader>
          {/* 로그인하지 않아도 질문 게시판은 둘러볼 수 있다 (REQ-HEADER-002). 주요 버튼은 로그인 하나만 둔다. */}
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.white}`} to={MAIN_PATH}>
            <span className={ICON} aria-hidden="true">
              forum
            </span>
            <span className="hidden sm:inline">질문 게시판 둘러보기</span>
            <span className="sm:hidden">둘러보기</span>
          </Link>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.yellow}`} to="/signup">
            회원가입
          </Link>
        </AuthHeader>

        <main className="flex-grow flex items-center justify-center py-10 px-4 sm:px-6">
          <div className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">
            {/* 왼쪽: 서비스 소개 */}
            <AuthShowcase className="lg:col-span-7" />

            {/* 오른쪽: 로그인 폼. 한 줄로 쌓이는 좁은 화면에서는 폼을 먼저 보여 준다 */}
            <section
              className={`${CARD} order-first lg:order-none lg:col-span-5 p-4 sm:p-6 flex flex-col justify-center`}
            >
              <div className="mb-6">
                <h2 className="text-lg font-extrabold text-devin-ink">반가워요</h2>
                <p className="text-sm font-medium text-devin-gray mt-1">
                  개발자를 위한 커넥트 플랫폼, <span className="font-bold text-devin-ink">Dev in_</span>
                </p>
              </div>

              <form className="space-y-5" id="loginForm" noValidate onSubmit={handleSubmit}>
                <div>
                  <label className={INPUT.label} htmlFor="userId">
                    아이디
                  </label>
                  <input
                    autoComplete="username"
                    className={INPUT.base}
                    id="userId"
                    name="userId"
                    onChange={(e) => setLoginId(e.target.value)}
                    placeholder="아이디 입력"
                    required
                    type="text"
                    value={loginId}
                  />
                </div>

                <div>
                  <label className={INPUT.label} htmlFor="password">
                    비밀번호
                  </label>
                  <div className="relative">
                    <span
                      className={`${ICON} absolute left-3 top-1/2 -translate-y-1/2 text-devin-gray pointer-events-none`}
                      aria-hidden="true"
                    >
                      lock
                    </span>
                    <input
                      autoComplete="current-password"
                      className={`${INPUT.base} pl-10 pr-11`}
                      id="password"
                      name="password"
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="비밀번호 입력"
                      required
                      type={showPassword ? "text" : "password"}
                      value={password}
                    />
                    {/* REQ-LOGIN-003: 비밀번호 표시/숨기기 (기본 숨김) */}
                    <button
                      aria-label={showPassword ? "비밀번호 숨기기" : "비밀번호 보기"}
                      aria-pressed={showPassword}
                      className={`absolute inset-y-0 right-1 my-1 px-2 flex items-center rounded text-devin-gray hover:text-devin-ink ${FOCUS}`}
                      id="togglePasswordBtn"
                      onClick={() => setShowPassword((v) => !v)}
                      type="button"
                    >
                      <span className={ICON} aria-hidden="true">
                        {showPassword ? "visibility_off" : "visibility"}
                      </span>
                    </button>
                  </div>
                </div>

                <button
                  className={`${buttonClass("primary")} w-full`}
                  disabled={!canSubmit}
                  id="loginSubmitBtn"
                  type="submit"
                >
                  {submitting ? "로그인 중..." : "로그인"}
                  <span className={ICON} aria-hidden="true">
                    arrow_forward
                  </span>
                </button>
              </form>

              <p className="mt-6 pt-4 border-t-devin border-devin-line flex items-center justify-center gap-2 flex-wrap text-xs font-semibold text-devin-gray">
                <Link className={LINK} to="/find-id">
                  아이디 찾기
                </Link>
                <span className="text-devin-gray-light" aria-hidden="true">
                  |
                </span>
                <Link className={LINK} to="/find-password">
                  비밀번호 찾기
                </Link>
                <span className="text-devin-gray-light" aria-hidden="true">
                  |
                </span>
                {/* REQ-LOGIN-008: 가입하기 → 회원가입 페이지 */}
                <Link className={`${LINK} font-bold text-devin-ink`} to="/signup">
                  회원가입
                </Link>
              </p>
            </section>
          </div>
        </main>

        <Footer />
        {error && <LoginFailedDialog error={error} onClose={() => setError(null)} />}
      </div>
    </div>
  );
}
